export const BODY: string = "\n<p>إذا كان لديك آيفون، فمعظم صورك ملفات HEIC، طلبت ذلك أم لا. تبدو رائعة على هاتفك، لكنها ترفض الفتح في أماكن كثيرة.</p>\n<p>تحويل HEIC إلى JPG هو الحل. JPG يُفتح في كل مكان، من حاسوب قديم إلى بوابة توظيف إلى طابعة.</p>\n<p>يشرح هذا الدليل ما هي HEIC، ولماذا تستخدمها أبل، وكيف تحوّلها بنظافة دون فقدان الجودة.</p>\n<h2 id=\"what-is-heic\">ما هي HEIC؟</h2>\n<p>HEIC صيغة صور حديثة من أبل، مبنية على ضغط فيديو متقدم. تحفظ الصور بحجم أصغر من JPG بجودة مماثلة.</p>\n<p>الاسم يعني صيغة صورة عالية الكفاءة. إنها كفؤة في الحجم، لكن توافقها محدود خارج أجهزة أبل.</p>\n<h2 id=\"why-iphones-use-heic\">لماذا تحفظ أجهزة آيفون الصور كـHEIC؟</h2>\n<p>لماذا تحفظ أجهزة آيفون الصور كـHEIC؟ لأنها توفر مساحة تخزين كبيرة. الصور تزن نصف حجم JPG تقريبًا بالجودة نفسها.</p>\n<p>أبل اختارت توفير المساحة على التوافق. على آيفون، كل شيء يعمل بسلاسة، لكن خارج آيفون تبدأ المشاكل.</p>\n<h2 id=\"why-windows-rejects-heic\">لماذا ترفض حواسيب ويندوز ملفات HEIC؟</h2>\n<p>لماذا ترفض حواسيب ويندوز ملفات HEIC؟ لأن ويندوز لا يدعم الصيغة افتراضيًا. تحتاج إلى برنامج إضافي أو تحويل إلى JPG.</p>\n<p>البرامج القديمة والبوابات والطابعات ترفض HEIC أيضًا. التحويل إلى JPG هو الحل العملي الوحيد في معظم الحالات.</p>\n<h2 id=\"how-decoding-works\">كيف يعمل فك تشفير HEIC في المتصفح؟</h2>\n<p>كيف يعمل فك تشفير HEIC في المتصفح؟ المتصفح يقرأ ملف HEIC ويفك ضغطه إلى بكسلات، ثم يعيد ترميزها كـJPG. كل ذلك يحدث على جهازك.</p>\n<p>فك التشفير يحتاج إلى معالجة أكثر من الصيغ الأخرى، لذلك قد يستغرق التحويل وقتًا أطول قليلًا. لكن النتيجة تستحق الانتظار.</p>\n<h2 id=\"quality-setting-90\">لماذا 90 بالمئة هي الجودة الافتراضية؟</h2>\n<p>لماذا 90 بالمئة هي الجودة الافتراضية؟ لأنها توازن بين الحجم والجودة. جودة 90 تحافظ على التفاصيل دون ملف ضخم.</p>\n<p>للصور المهمة استخدم 95، وللمشاركة اليومية يكفي 85. الجودة 90 هي النقطة المثالية لمعظم الاستخدامات.</p>\n<h2 id=\"file-size-after-conversion\">لماذا ملفات JPG المحوّلة أكبر من HEIC؟</h2>\n<p>لماذا ملفات JPG المحوّلة أكبر من HEIC؟ لأن JPG أقل كفاءة في الضغط. الصورة نفسها تحتاج مساحة أكبر بصيغة JPG.</p>\n<p>هذا طبيعي وليس خطأ. أنت تستبدل الكفاءة بالتوافق، والملف الأكبر هو ثمن فتح الصورة في كل مكان.</p>\n<h2 id=\"live-photos\">ماذا يحدث للصور الحية؟</h2>\n<p>ماذا يحدث للصور الحية؟ Live Photos تحمل فيديو قصيرًا مع الصورة. عند التحويل إلى JPG، تحصل على الصورة الثابتة فقط، ويفقد الفيديو.</p>\n<p>إذا أردت الاحتفاظ بالحركة، فحوّل Live Photo إلى فيديو أو GIF بدل JPG. التحويل إلى JPG يحفظ اللقطة لا الحركة.</p>\n<h2 id=\"orientation-and-colour\">الاتجاه واللون والدقة</h2>\n<p>الاتجاه واللون والدقة: التحويل يحافظ على اتجاه الصورة وألوانها ودقتها. الصورة المحوّلة تبدو كما كانت على آيفون.</p>\n<p>إذا ظهرت الصورة مقلوبة بعد التحويل، فالسبب بيانات الاتجاه في الملف الأصلي. دوّر الصورة قبل التحويل أو بعده.</p>\n<h2 id=\"batch-converting-albums\">كيف تحوّل ألبومات كاملة دفعة واحدة؟</h2>\n<p>لتحويل ألبومات كاملة دفعة واحدة، ارفع كل صور HEIC وحوّلها إلى JPG بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>راجع عينة من النتائج قبل الاعتماد على الدفعة كلها. إذا بدت العينة جيدة، فغالبًا بقية الصور بنفس الجودة.</p>\n<h2 id=\"heic-vs-heif\">HEIC مقابل HEIF: ما الفرق؟</h2>\n<p>HEIC مقابل HEIF: ما الفرق؟ HEIF هو اسم الصيغة العامة، وHEIC هو إصدار أبل منها. عمليًا، هما الشيء نفسه في معظم الاستخدامات.</p>\n<p>إذا رأيت ملف HEIF، فتعامل معه مثل HEIC. التحويل إلى JPG يعمل بالطريقة نفسها.</p>\n<h2 id=\"stop-future-heic\">كيف تمنع حفظ الصور المستقبلية كـHEIC؟</h2>\n<p>لمنع حفظ الصور المستقبلية كـHEIC، غيّر إعدادات الكاميرا في آيفون إلى الأكثر توافقًا. بهذا تحفظ الصور الجديدة كـJPG مباشرة.</p>\n<p>الإعداد في الكاميرا ثم الصيغ ثم الأكثر توافقًا. الصور الجديدة ستكون JPG، والصور القديمة تبقى HEIC حتى تحوّلها.</p>\n<h2 id=\"common-problems\">مشاكل شائعة وحلولها</h2>\n<p>مشاكل شائعة وحلولها: ملف يفشل في التحويل قد يكون تالفًا أو بصيغة غير مدعومة. تحقق من فتحه في تطبيق الصور أولًا.</p>\n<p>إذا ظهرت الألوان باهتة بعد التحويل، فأعد التحويل بجودة أعلى. وللأحجام الصغيرة، استخدم <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a> بعد التحويل.</p>\n<h2 id=\"sharing-with-family\">كيف تشارك صور آيفون مع العائلة؟</h2>\n<p>لمشاركة صور آيفون مع العائلة، حوّلها إلى JPG أولًا. العائلة قد تستخدم أجهزة أندرويد أو حواسيب ويندوز لا تفتح HEIC.</p>\n<p>أرسل النسخ المحوّلة بدل الأصل. بهذا تضمن أن الجميع يستطيع فتح الصور دون مشاكل.</p>\n<h2 id=\"heic-in-work-documents\">صور HEIC في مستندات العمل</h2>\n<p>صور HEIC في مستندات العمل: كثير من برامج العمل لا تقبل HEIC. حوّل الصور إلى JPG قبل إدراجها في مستندات أو عروض تقديمية.</p>\n<p>التحويل المسبق يمنع مفاجآت يوم العرض. تحقق من أن كل صورة في مستندك تفتح بشكل صحيح قبل الاجتماع.</p>\n<h2 id=\"printing-iphone-photos\">كيف تطبع صور آيفون؟</h2>\n<p>لطباعة صور آيفون، حوّلها إلى JPG أولًا. معظم خدمات الطباعة والطابعات لا تقبل HEIC مباشرة.</p>\n<p>اطبع من ملف JPG المحوّل بجودة عالية. الطباعة تحتاج دقة كاملة، لذلك استخدم جودة 95 للصور التي ستطبعها.</p>\n<h2 id=\"moving-to-new-phone\">كيف تنقل الصور إلى هاتف جديد؟</h2>\n<p>لنقل الصور إلى هاتف جديد، حوّل نسخًا إلى JPG للهواتف غير آيفون. الهاتف الجديد من أبل يقبل HEIC دون مشاكل.</p>\n<p>إذا انتقلت من آيفون إلى أندرويد، فحوّل كل صورك إلى JPG قبل النقل. وللخطوات العملية، استخدم <a href=\"/ar/tahwil-heic-ila-jpg/\">محول HEIC إلى JPG</a>، واقرأ <a href=\"/ar/blog/kayfiyya-tahwil-heic-ila-jpg/\">كيفية تحويل HEIC إلى JPG</a> و<a href=\"/ar/blog/heic-vs-jpg/\">HEIC مقابل JPG</a>، أو جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> لصيغ أخرى.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يمكنني تحويل HEIC إلى JPG على حاسوب ويندوز؟","answer":"نعم، يعمل التحويل في متصفح حاسوب ويندوز دون تثبيت أي برنامج. افتح الأداة في المتصفح وارفع صورك وحوّلها."},{"question":"هل أفقد جودة الصورة عند تحويل HEIC إلى JPG؟","answer":"فقدان الجودة ضئيل جدًا عند استخدام جودة 90. التحويل من HEIC إلى JPG بجودة عالية يحافظ على التفاصيل، ومعظم العيون لا تلاحظ أي فرق."},{"question":"هل يمكنني تحويل صور HEIC مباشرة على آيفون؟","answer":"نعم، يمكنك التحويل مباشرة على آيفون بفتح الأداة في متصفح سفاري ورفع الصور من معرضك. التحويل يحدث على جهازك."},{"question":"ما أفضل إعداد جودة لتحويل HEIC إلى JPG؟","answer":"جودة 90 هي الإعداد الافتراضي لأنها توازن بين الحجم والجودة. للصور المهمة استخدم 95، وللمشاركة اليومية يكفي 85."},{"question":"هل يزيل تحويل HEIC إلى JPG بيانات موقع صوري؟","answer":"الأداة تزيل بيانات الموقع أثناء التحويل. الملف المحوّل لا يحمل وسوم GPS، وهذا يحمي خصوصيتك عند مشاركة الصور."},{"question":"هل يمكنني تحويل ملف HEIC إلى PNG بدل JPG؟","answer":"نعم، يمكنك التحويل إلى PNG بدل JPG. اختر PNG كصيغة إخراج إذا احتجت إلى شفافية أو حدة كاملة للنصوص."}];
